-- Photos (Wikimedia Commons). URL and file page are rebuilt from the Commons path.
create temp table _ph on commit drop as
select v.*, 'https://upload.wikimedia.org/wikipedia/commons/' || case when v.thumb
    then 'thumb/' || v.path || '/1280px-' || split_part(v.path, '/', 3) else v.path end as url,
  'https://commons.wikimedia.org/wiki/File:' || split_part(v.path, '/', 3) as page
