update public.destinations d set cover_photo_url = p.url, cover_photo_credit = p.credit, cover_photo_source_url = p.page
from _ph p where p.kind = 'C' and p.target = 'd:' || d.name_en;
update public.stations s set photo_url = p.url, photo_credit = p.credit, photo_source_url = p.page
from _ph p where p.kind = 'C' and p.target = 's:' || s.code;
update public.trains t set photo_url = p.url, photo_credit = p.credit, photo_source_url = p.page
from _ph p join (values ('t:Podi Menike','1005'), ('t:Podi Menike','1006'), ('t:Udarata Menike','1015'), ('t:Udarata Menike','1016'), ('t:Yal Devi','4077'), ('t:Yal Devi','4078'), ('t:Udaya Devi','6011'), ('t:Udaya Devi','6012'), ('t:Ruhunu Kumari','8058'), ('t:Ruhunu Kumari','8059')) m(target, n) on m.target = p.target
where p.kind = 'C' and t.number = m.n;
delete from public.destination_photos where destination_id in
  (select d.id from public.destinations d join _ph p on p.kind = 'G' and p.target = d.name_en);
insert into public.destination_photos (destination_id, url, sort, credit, source_url)
select d.id, p.url, p.ord, p.credit, p.page from _ph p join public.destinations d on d.name_en = p.target
where p.kind = 'G' on conflict do nothing;

commit;
